// Pre-built Savage Worlds (SWADE) NPCs, in the core-book bestiary style.
// Attributes/skills are trait-die strings; `wild` marks Wild Cards, who roll
// the d6 Wild Die on traits and can take three Wounds where an Extra takes
// one.
//
// Nothing here has hit points, because SWADE has none: a damage roll is
// compared to Toughness, and what comes back is Shaken or a Wound. So a row
// states neither — Toughness derives from Vigor, armor and Size the same way
// it does on a player's sheet, and the wound track comes from `wild`. A row
// that wants a creature tougher says so where the book does: a bigger Vigor
// die, thicker armor, or a Size trait.
//
// `ac` on the entry is derived Parry and `hp` is derived Toughness — both are
// the shared NpcEntry's generic fields, filled with the SWADE numbers that
// answer the same question. `challenge` is a rough tier for sorting.

import { swade, dieSides, swadeToughness } from '../systems/swade.js';
import { CONTENT_SWADE } from './contentSwade.js';
import { slug, type NpcEntry } from './npcTypes.js';
import type { SheetData } from '../types.js';

type Attrs = [string, string, string, string, string]; // agility, smarts, spirit, strength, vigor
type Skill = [string, string];                          // name, die
/** Optional mechanics: a forced trait roll (with outcome + inflicted state)
 *  and/or an area template — resolved by the generic attack pipeline. */
interface AttackMeta {
  save?: 'agility' | 'smarts' | 'spirit' | 'strength' | 'vigor';
  onSave?: 'half' | 'negate';
  condition?: string;
  aoeShape?: 'cone' | 'sphere' | 'line';
  aoeSize?: number;
  /** SWADE blast template in tiles-beyond-target (Small 1, Medium 3, Large 5). */
  aoeHexes?: number;
  /** Armor Piercing — ignores this much of the target's Armor. */
  ap?: number;
  /** A Heavy Weapon: cannon, torpedo, main gun. The only thing that hurts
   *  the Heavy Armor every Gargantuan creature and warship carries. */
  heavy?: boolean;
  /** Venomous: a hit that at least Shakes forces a Vigor roll at `poisonMod`;
   *  failing it costs `poisonEffect`. SWADE poison is never a to-hit rider —
   *  the bite has to tell before the venom is in. */
  poison?: boolean;
  /** Same machinery as poison; the card just calls it Infection. */
  infection?: boolean;
  poisonMod?: number;
  poisonEffect?: 'fatigue' | 'shaken' | 'incapacitated' | 'paralyzed';
  /** Ignores up to 4 points of Scale penalty against something smaller. */
  swat?: boolean;
}
type Attack = [string, 'Fighting' | 'Shooting' | 'Athletics', string, string, number, AttackMeta?]; // name, skill, damage, dtype, range ft
type Armor = [string, number, number];                  // name, armor, parryBonus

interface Row {
  name: string;
  category: string;
  tier: number;
  wild: boolean;
  attrs: Attrs;
  skills: Skill[];
  attacks: Attack[];
  armor?: Armor[];
  /** Racial traits granting a flat Toughness bonus (Size, mainly), as
   *  [name, bonus] — feeds the same derived-stat path Edges use. */
  traits?: [string, number][];
  /** Edge names; their live modifier columns are pulled from the compendium
   *  so a named Edge actually moves the sheet (Mr. Fix It's +2 Repair, …). */
  edges?: string[];
  /** [name, severity] — Hindrances are roleplay guidance plus any modifier
   *  columns the compendium entry carries. */
  hindrances?: [string, 'Minor' | 'Major'][];
  /** Non-weapon kit: [name, notes]. Rollable weapons belong in `attacks`. */
  gear?: [string, string][];
  pace?: number;
  /** Comma list of damage types the engine shifts by 4 (sheet `resist`). */
  resist?: string;
  /** Comma list of damage types the engine zeroes (sheet `immune` field). */
  immune?: string;
  /** Comma list of damage types that come in 4 higher — and, for an
   *  Invulnerable creature, the only things that can Wound it at all. */
  vulnerable?: string;
  /** Being Shaken twice does not become a Wound. */
  hardy?: boolean;
  /** No Fear checks, and Intimidation finds nothing to grip. */
  fearless?: boolean;
  /** Only Heavy Weapons can hurt it. Gargantuan (Size 12+) creatures get this
   *  from their Size and need not state it; the flag is for the armoured
   *  thing that is merely Huge, like a tank. */
  heavyArmor?: boolean;
  /** Heals a Wound on a Vigor roll — every round (fast) or on the DM's call. */
  regeneration?: 'fast' | 'slow';
  /**
   * This row is a MACHINE: it gets the vehicle sheet (Handling, Top Speed,
   * Toughness-with-Armor, Crew) instead of a creature's, takes damage on the
   * vehicle ladder, and spawns already rideable with this many seats.
   */
  vehicle?: {
    kind: 'ground' | 'watercraft' | 'aircraft' | 'spacecraft';
    size: number; handling: number; topSpeed: number;
    toughness: number; armor: number;
    crew: number; passengers?: number;
    cost?: string; features?: string[];
  };
  /** Never alive: repaired, not healed. */
  construct?: boolean;
  /** Physically dead and still going: +2 Toughness, magic mends it. */
  undead?: boolean;
  /** Nothing Wounds it except what its `vulnerable` list names. */
  invulnerable?: boolean;
  /** An elite Extra: one Wound before it drops, or two. */
  resilient?: 'resilient' | 'veryResilient';
  /** Ignores the Dim/Dark attack penalty (not Pitch Darkness). */
  lowLightVision?: boolean;
  /** Halves illumination penalties against anything that gives off heat. */
  infravision?: boolean;
  note?: string;
}

